set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import json,base64,hashlib
payload=json.loads('{"rag/eval/README.md": "", "rag/eval/catalog/answer.md": "", "rag/eval/catalog/inventory.json": "", "rag/eval/catalog/langgraph.md": "", "rag/eval/catalog/mixed.md": "", "rag/eval/catalog/planning.md": "", "rag/eval/catalog/retrieval.md": "", "rag/eval/catalog/routing.md": "", "rag/eval/catalog/ticket_sql.md": ""}')
for n,b in payload.items():
 p=Path(n);data=base64.b64decode(b);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data);assert hashlib.sha256(p.read_bytes()).hexdigest()==hashlib.sha256(data).hexdigest()
print('Synced classification files:',len(payload))
PY
